 void slotset(int fd,Conn*c,int kind,uint32_t events){if(fd<0)return;if((size_t)fd>=slots.size())slots.resize(fd+1);auto &s=slots[fd];s.c=c;s.kind=kind;s.gen=++seq;epoll_event ev{};ev.events=events;ev.data.u64=((uint64_t)s.gen<<32)|(unsigned)fd;epoll_ctl(ep,EPOLL_CTL_ADD,fd,&ev);}
