 static bool hop(const string&n,const string&conn){return n=="connection"||n=="keep-alive"||n=="proxy-authenticate"||n=="proxy-authorization"||n=="te"||n=="trailer"||n=="transfer-encoding"||n=="upgrade"||n=="content-length"||has_token(conn,n);}
