 int local(const string&path,int &fd,size_t &len){vector<string> parts;size_t p=0;bool trail=path.size()>1&&path.back()=='/';while(p<path.size()){while(p<path.size()&&path[p]=='/')p++;size_t q=path.find('/',p);if(q==string::npos)q=path.size();if(q>p){string s=path.substr(p,q-p);if(s=="..")return 403;if(s!=".")parts.push_back(s);}p=q;}if(parts.empty())return 403;int dir=dup(root);if(dir<0)return 500;for(size_t i=0;i<parts.size();i++){struct stat st;if(fstatat(dir,parts[i].c_str(),&st,AT_SYMLINK_NOFOLLOW)){int x=errno;close(dir);return x==ENOENT||x==ENOTDIR?404:403;}if(S_ISLNK(st.st_mode)){close(dir);return 403;}bool last=i+1==parts.size();if(!last&&!S_ISDIR(st.st_mode)){close(dir);return 404;}if(last&&!S_ISREG(st.st_mode)){close(dir);return 403;}int f=openat(dir,parts[i].c_str(),O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK|(last?0:O_DIRECTORY));close(dir);if(f<0)return errno==ENOENT?404:403;if(fstat(f,&st)){close(f);return 403;}if(last){if(!S_ISREG(st.st_mode)||trail||st.st_size<0){close(f);return 403;}fd=f;len=(size_t)st.st_size;return 200;}if(!S_ISDIR(st.st_mode)){close(f);return 403;}dir=f;}close(dir);return 403;}
